files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-inline-size: 600px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

h1,
h2,
p,
ul {
  margin: 0;
}

ul {
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
  text-decoration: none;
}

.visually-hidden {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5em 1em;
  background-color: #6dc1fd;
}

.title {
  font-weight: 800;
  font-size: 45px;
  text-transform: uppercase;
}

.menu {
  position: relative;
}

.menu__button {
  inline-size: 40px;
  block-size: 40px;
  border: 4px solid #000;
  background-color: transparent;
  background-image: url(../svg/profile.svg);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  cursor: pointer;
}

.menu.is-opened .menu__button {
  background-image: url(../svg/close.svg);
}

.menu__button:hover {
  background-color: #ffc802;
}

.menu ul {
  position: absolute;
  right: 0  ;
  bottom: 0;
  z-index: 2;
  display: none;
  translate: 0 120%;
}

.menu.is-opened ul {
  display: block;
}

.menu li:not(:last-child) {
  margin-block-end: 0.5em;
}

.menu a {
  display: block;
  border: 1px solid #000;
  padding: 0.5em 1em;
  font-weight: bold;
  text-align: center;
  background-color: #fff;
}

.menu a:hover {
  background-color: #ffc802;
}

.content {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 1em;
  padding: 3em 1em;
}

.feed__item:not(:last-child) {
  margin-block-end: 2em;
}

.card {
  padding: 2em;
  box-shadow: 0 0 0.5em rgb(0 0 0 / 0.2);
  background-color: #fff;
}

.card__title {
  margin-block-end: 0.5em;
  font-weight: 800;
  font-size: 31px;
  text-transform: uppercase;
}

.card__preview-text {
  margin-block-end: 2em;
}

.card__more-link {
  border: 1px solid #000;
  padding: 0.5em 2em;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
}

.card__more-link:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.card__more-link:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.hashtags {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  align-content: start;
  gap: 0.5em;
}

.hashtags__link {
  display: block;
  block-size: fit-content;
  border: 1px solid #000;
  padding: 0.5em 1em;
  font-weight: bold;
  text-align: center;
  background-color: #fff;
}

.hashtags__link:hover {
  background-color: #ffc802;
}
body:has(.menu.is-opened) .hashtags {
  filter: blur(5px);
  pointer-events: none;
}
